import{_ as l,C as o,c as s,o as n,j as c,G as d,ak as r,a as p}from"./chunks/framework.D7ejh1zC.js";const q=JSON.parse('{"title":"工作中项目 git 如何管理，冲突如何解决","description":"","frontmatter":{},"headers":[],"relativePath":"module/git/工作中项目git如何管理，冲突如何解决.md","filePath":"concept/module/git/工作中项目git如何管理，冲突如何解决.md","lastUpdated":1786880804000}'),g={name:"module/git/工作中项目git如何管理，冲突如何解决.md"};function u(m,e,h,_,b,f){const t=o("mdInfo"),i=o("NolebaseGitContributors"),a=o("NolebaseGitChangelog");return n(),s("div",null,[e[0]||(e[0]=c("h1",{id:"工作中项目-git-如何管理-冲突如何解决",tabindex:"-1"},[p("工作中项目 git 如何管理，冲突如何解决 "),c("a",{class:"header-anchor",href:"#工作中项目-git-如何管理-冲突如何解决","aria-label":'Permalink to "工作中项目 git 如何管理，冲突如何解决"'},"​")],-1)),d(t),e[1]||(e[1]=r('<blockquote><p>涉及知识点</p><ol><li>公司中 <code>git</code> 仓库管理方式是怎样的</li><li>代码为何 <code>push</code> 不上线上仓库</li><li>如何解决冲突</li></ol></blockquote><h2 id="git主流两种管理方式" tabindex="-1">Git主流两种管理方式 <a class="header-anchor" href="#git主流两种管理方式" aria-label="Permalink to &quot;Git主流两种管理方式&quot;">​</a></h2><h3 id="git单仓库模式" tabindex="-1">Git单仓库模式 <a class="header-anchor" href="#git单仓库模式" aria-label="Permalink to &quot;Git单仓库模式&quot;">​</a></h3><p>进入一家公司，领导会给你分配一个 <code>git</code> 账号以及项目代码仓库，此时可以去到仓库地址，基于 <code>master</code> 主分支新建一个自己的代码分支，可以用 <code>git checkout -b</code> 命令，也可以在线上仓库新建分支，本案例选择在线上仓库新建一个名为 <code>daodao-new</code> 分支。</p><p>新建完毕后 <code>git clone</code> 克隆代码到本地，此时需要注意克隆下来的是在主分支，且 <code>git branch</code> 查看所有分支时也只有 <code>master</code> 主分支，因此需要 <code>git checkout -b daodao-new</code> 切换到对应的分支，注意分支名要和之前创建的一样。切换完毕后 <code>git status</code> 查看状态，提示 <code>On branch daodao-new</code> 即为成功。</p><p>写完代码后，<code>git add .</code> 提交代码，<code>git commit -m &#39;提交信息&#39;</code> 提交到本地仓库，此时不能直接 <code>git push</code> 提交远程仓库，这会报错，因为 <code>git push</code> 默认提交到 <code>master</code> 主分支，应该要 <code>git push origin daodao-new</code> 提交到远程仓库。</p><div class="info custom-block github-alert"><p class="custom-block-title">提示</p><p><code>origin</code> 表示远端，<code>daodao-new</code> 表示分支名，整条命令表示将本地 <code>daodao-new</code> 分支提交到远程仓库。</p></div><p>后续开发完后就需要代码合并了，此时需要将代码合并到主分支，<code>git checkout master</code> 切换到主分支，先 <code>git pull</code> 拉取最新代码，然后 <code>git merge daodao-new</code> 合并代码，合并完毕后 <code>git push</code> 提交到远程仓库。</p><h3 id="git多仓库模式" tabindex="-1">Git多仓库模式 <a class="header-anchor" href="#git多仓库模式" aria-label="Permalink to &quot;Git多仓库模式&quot;">​</a></h3><p>到公司主仓库下找到对应项目代码仓库，点击右上角 <code>fork</code> 按钮，将代码仓库复制一份到自己的账号下，此时会提示你选择一个目标仓库，选择自己的账号。此时开发都是在自己的账号下开发，即使本地搞崩了也可以重新 <code>fork</code> 重新开发，不用担心影响主仓库。</p><p><code>fork</code> 完毕后，<code>git clone</code> 代码到本地，注意 <code>clone</code> 的是自己账号的地址。修改完毕后，<code>git add .</code> 提交代码，<code>git commit -m &#39;提交信息&#39;</code> 提交到本地仓库，<code>git push</code> 推送到主分支。</p><p>如果提示 <code>Access denied 403</code>，则表示当前到 <code>git</code> 账号没有权限，需要修改 <code>git</code> 的账号密码。电脑修改 <code>git</code> 账号密码步骤如下：</p><ol><li>设置打开控制面板，找到「所有控制面选项」-&gt;「用户账户」-&gt;「管理账户」</li><li>点击左侧「管理我的凭据」，选择「Windows 凭据」</li><li>找到 <code>git</code>，点击「编辑」，修改账号密码即可</li></ol><p>开发完且代码提交完毕后，需要将代码合并到主仓库，此时需要点击主仓库右上角 <code>Pull requests</code> 按钮，点击 <code>New pull request</code> 按钮，选择要合并的分支，点击 <code>Create pull request</code> 按钮，填写合并信息，点击 <code>Create pull request</code> 按钮，等待管理员审核即可。</p><p>下面来一个一图流总结：</p><p><img src="https://pic1.imgdb.cn/item/67dcd87688c538a9b5c2577c.png" alt="一图流总结" loading="lazy"></p><h3 id="git冲突原因和解决" tabindex="-1">Git冲突原因和解决 <a class="header-anchor" href="#git冲突原因和解决" aria-label="Permalink to &quot;Git冲突原因和解决&quot;">​</a></h3><ol><li><p>账号无权限</p><p>此时申请账号权限即可。</p></li><li><p>本地比线上落后</p><p><img src="https://pic1.imgdb.cn/item/67dcd93c88c538a9b5c2594d.png" alt="图解" loading="lazy"></p><p>解决方案为：</p><ul><li>先 <code>git pull</code> 拉取线上代码</li><li>查看是否有冲突，如果有冲突，解决冲突，保留谁的代码，还是双方代码都保留</li><li>解决冲突后，<code>git add .</code> 提交代码，<code>git commit -m &#39;提交信息&#39;</code> 提交到本地仓库，<code>git push</code> 提交到线上仓库</li></ul></li></ol>',18)),d(i),d(a)])}const G=l(g,[["render",u]]);export{q as __pageData,G as default};
